    }

    function _fullRound(uint256[4] memory s, uint256 rc0, uint256 rc1, uint256 rc2, uint256 rc3) internal pure {
        uint256 pp = P;
        s[0] = _sbox5(addmod(s[0], rc0, pp));
        s[1] = _sbox5(addmod(s[1], rc1, pp));
        s[2] = _sbox5(addmod(s[2], rc2, pp));
        s[3] = _sbox5(addmod(s[3], rc3, pp));
        _extMds(s);
    }

    function _partialRound(uint256[4] memory s, uint256 rc) internal pure {
        s[0] = _sbox5(addmod(s[0], rc, P));
        _intMds(s);
    }

    function _sbox5(uint256 x) internal pure returns (uint256) {
        uint256 x2 = mulmod(x, x, P);
        uint256 x4 = mulmod(x2, x2, P);
        return mulmod(x4, x, P);
    }

    /// @dev External MDS matrix multiplication (Barretenberg M4, ~13 additions).
    function _extMds(uint256[4] memory s) internal pure {
        uint256 pp = P;
        uint256 t0 = addmod(s[0], s[1], pp);           // A+B
        uint256 t1 = addmod(s[2], s[3], pp);           // C+D
        uint256 t2 = addmod(addmod(s[1], s[1], pp), t1, pp); // 2B+C+D
        uint256 t3 = addmod(addmod(s[3], s[3], pp), t0, pp); // A+B+2D
        uint256 t1d = addmod(t1, t1, pp);
        uint256 t4 = addmod(addmod(t1d, t1d, pp), t3, pp);   // A+B+4C+6D
        uint256 t0d = addmod(t0, t0, pp);
        uint256 t5 = addmod(addmod(t0d, t0d, pp), t2, pp);   // 4A+6B+C+D
        s[0] = addmod(t3, t5, pp); // 5A+7B+C+3D
        s[1] = t5;                  // 4A+6B+C+D
        s[2] = addmod(t2, t4, pp); // A+3B+5C+7D
        s[3] = t4;                  // A+B+4C+6D
    }

    /// @dev Internal MDS: state[i] = state[i] * diag[i] + sum(state).
    function _intMds(uint256[4] memory s) internal pure {
        uint256 pp = P;
        uint256 sum = addmod(addmod(s[0], s[1], pp), addmod(s[2], s[3], pp), pp);
        s[0] = addmod(mulmod(D0, s[0], pp), sum, pp);
        s[1] = addmod(mulmod(D1, s[1], pp), sum, pp);
        s[2] = addmod(mulmod(D2, s[2], pp), sum, pp);
        s[3] = addmod(mulmod(D3, s[3], pp), sum, pp);
    }
}

